const noiseScale = 0.001;
let c = 0;
const num = 100;

function setup() {
  createCanvas(windowWidth, windowHeight);
  rectMode(CENTER);
  noStroke();

  c = random(255);

  // noLoop() removed for animation
}

function draw() {
  background(c);

  for (let i = 0; i < num; i++) {
    if (i == num - 2) {
      fill(c);
    } else if (i == num - 1) {
      // fill("#EB8882");
    } else {
      if (random(100) < 10) {
        fill("#EB8882");
      } else {
        fill(random(0, 255));
      }
    }

    let isFill = true;
    for (let x = 0; x < width; x++) {
      if (i == num - 1) {
        if (x % 13 == 0) {
          isFill = !isFill;
        }
        if (isFill) {
          fill("#EB8882");
        } else {
          noFill();
        }
      }
      let t = map(x, 0, width, 0, PI);

      let yMax = (height / 2) * sin(t);
      let y = map(noise(i * 0.01, x * noiseScale * 2), 0, 1, -yMax, yMax) + height / 2;

      let hMax = (height / 2) * sin(t);
      let h = map(noise(x * noiseScale, y * noiseScale), 0, 1, 0, hMax);
      rect(x, y, 1, h);
    }

  }
}
